`src/envs/dev/infra/logs.ts`
```typescript
import { ReaderIam, SecureBucket } from "../../../composites/index.js";

const ENV = "dev";
const REGION = "us-east-1";

export const logs = SecureBucket({
  name: "myapp-logs-dev",
  env: ENV,
  region: REGION,
});

export const logsReader = ReaderIam({
  name: "myapp-logs-dev",
  env: ENV,
  bucketName: "myapp-logs-dev",
  trust: { mode: "account", accountID: "123456789012" },
  additionalActions: ["s3:PutObject"],
  programmaticAccess: true,
});
```

`src/envs/prod/infra/logs.ts`
```typescript
import { ReaderIam, SecureBucket } from "../../../composites/index.js";

const ENV = "prod";
const REGION = "us-east-1";
const APP_NAMESPACE = "app";
const SERVICE_ACCOUNT = "myapp";

export const logs = SecureBucket({
  name: "myapp-logs-prod",
  env: ENV,
  region: REGION,
});

export const logsReader = ReaderIam({
  name: "myapp-logs-prod",
  env: ENV,
  bucketName: "myapp-logs-prod",
  trust: {
    mode: "oidc",
    providerARN: "arn:aws:iam::123456789012:oidc-provider/oidc.eks.us-east-1.amazonaws.com/id/EXAMPLEPROD",
    issuerHost: "oidc.eks.us-east-1.amazonaws.com/id/EXAMPLEPROD",
    serviceAccountNamespace: APP_NAMESPACE,
    serviceAccountName: SERVICE_ACCOUNT,
  },
  additionalActions: ["s3:PutObject"],
  programmaticAccess: false,
  podIdentity: {
    clusterName: "myapp-prod",
    serviceAccountNamespace: APP_NAMESPACE,
    serviceAccountName: SERVICE_ACCOUNT,
  },
});
```

Both files follow the pattern established in the respective environment's `main.ts`. Each declares:
- A `SecureBucket` for `myapp-logs-{env}`, inheriting SPEC criterion 1 guardrails (versioning, encryption, public-access block) from the composite factory
- An independent `ReaderIam` identity scoped solely to the logs bucket, with `additionalActions: ["s3:PutObject"]` to grant write access alongside the baseline `s3:GetObject`
- The same trust mechanism as each environment's existing `reader`: account-mode in dev with programmatic access, OIDC-mode in prod with pod-identity binding to the `myapp` service account in the `app` namespace

The `chant build src/envs/<env>/infra` discovery picks up both `main.ts` and `logs.ts`, emitting all resources to the same manifest.
